    G[811] = lambda T: np.exp( -(-1*gibbs_sp('CH4',T)+1*gibbs_sp('CH2_1',T)+1*gibbs_sp('H',T)+1*gibbs_sp('H',T) ) )*(corr*T)**-2
    G[813] = lambda T: np.exp( -(-1*gibbs_sp('CH4',T)+1*gibbs_sp('CH',T)+1*gibbs_sp('H2',T)+1*gibbs_sp('H',T) ) )*(corr*T)**-2
    G[815] = lambda T: np.exp( -(-1*gibbs_sp('CH3',T)+1*gibbs_sp('CH',T)+1*gibbs_sp('H2',T) ) )*(corr*T)**-1
