    G[821] = lambda T: np.exp( -(-1*gibbs_sp('H2',T)+1*gibbs_sp('H',T)+1*gibbs_sp('H',T) ) )*(corr*T)**-1
    G[823] = lambda T: np.exp( -(-1*gibbs_sp('C2H2',T)+1*gibbs_sp('C2H',T)+1*gibbs_sp('H',T) ) )*(corr*T)**-1
    G[825] = lambda T: np.exp( -(-1*gibbs_sp('CO2',T)+1*gibbs_sp('CO',T)+1*gibbs_sp('O',T) ) )*(corr*T)**-1
    G[827] = lambda T: np.exp( -(-1*gibbs_sp('CO2',T)+1*gibbs_sp('CO',T)+1*gibbs_sp('O_1',T) ) )*(corr*T)**-1
    G[829] = lambda T: np.exp( -(-1*gibbs_sp('C2H4',T)+1*gibbs_sp('C2H2',T)+1*gibbs_sp('H2',T) ) )*(corr*T)**-1
    G[831] = lambda T: np.exp( -(-1*gibbs_sp('C2H4',T)+1*gibbs_sp('C2H2',T)+1*gibbs_sp('H',T)+1*gibbs_sp('H',T) ) )*(corr*T)**-2
    G[833] = lambda T: np.exp( -(-1*gibbs_sp('C2H4',T)+1*gibbs_sp('C2H3',T)+1*gibbs_sp('H',T) ) )*(corr*T)**-1
    G[835] = lambda T: np.exp( -(-1*gibbs_sp('C2H6',T)+1*gibbs_sp('C2H4',T)+1*gibbs_sp('H2',T) ) )*(corr*T)**-1
    G[837] = lambda T: np.exp( -(-1*gibbs_sp('C2H6',T)+1*gibbs_sp('C2H4',T)+1*gibbs_sp('H',T)+1*gibbs_sp('H',T) ) )*(corr*T)**-2
    G[839] = lambda T: np.exp( -(-1*gibbs_sp('C2H6',T)+1*gibbs_sp('C2H2',T)+1*gibbs_sp('H2',T)+1*gibbs_sp('H2',T) ) )*(corr*T)**-2
    G[841] = lambda T: np.exp( -(-1*gibbs_sp('C2H6',T)+1*gibbs_sp('CH4',T)+1*gibbs_sp('CH2_1',T) ) )*(corr*T)**-1
