    G[845] = lambda T: np.exp( -(-1*gibbs_sp('OH',T)+1*gibbs_sp('H',T)+1*gibbs_sp('O',T) ) )*(corr*T)**-1
    G[847] = lambda T: np.exp( -(-1*gibbs_sp('HCO',T)+1*gibbs_sp('H',T)+1*gibbs_sp('CO',T) ) )*(corr*T)**-1
